                        name: "对话节点",
                        dialogues: [
                            {
                                id: 12032001,
                                content: "今天天氣真好呀~是適合冒險的日子！",
                                voice: "story/1201/120113/1E1EF02A",
                                npc: 211001,
                            },
                        ],
